input.sparql:
SELECT ?point ?ts WHERE {
  ?point brick:hasProperty ?prop .
  ?point ref:hasTimeseriesId ?ts .
  ?prop a brick:ElectricPower ; brick:hasSubProperty* ?prop .
}

SELECT ?point ?ts WHERE {
  ?point a brick:ElectricPower .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

SELECT ?p ?class ?ts WHERE {
  ?p a ?class .
  FILTER (STR(?class) LIKE "%Electric%" || STR(?class) LIKE "%Meter%" || STR(?class) LIKE "%Power%")
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?class ?ts WHERE {
  ?p a ?class .
  ?class a rdfs:Class .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER (STR(?class) LIKE "%Electric%" || STR(?class) LIKE "%Meter%" || STR(?class) LIKE "%Power%")
}

SELECT ?p ?class ?ts WHERE {
  ?p a [rdfs:label "Electric Power Sensor"] .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?ts WHERE {
  ?p a brick:Electric_Power_Sensor .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?class ?ts WHERE {
  ?p a ?class .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  VALUES ?class { brick:Electric_Power_Sensor brick:Power_Sensor brick:Electrical_Meter brick:Building_Electrical_Meter }
}
